## Building a To-Do List Manager

### Task Structure

```xiom
enum TaskStatus {
  Pending;
  Completed;
}

type Task {
  id: Int;
  title: Str;
  status: TaskStatus;
  priority: Int;
}

type TodoList {
  tasks: Vec[Task];
  next_id: Int;
}
```

### Adding Tasks

```xiom
fn add_task(list: &mut TodoList, title: Str, priority: Int) -> Int {
  let task = Task{
    id: list.next_id,
    title: title,
    status: TaskStatus.Pending,
    priority: priority
  };
  list.tasks.push(task);
  list.next_id += 1;
  list.next_id - 1
}
```

### Completing and Removing

```xiom
fn complete_task(list: &mut TodoList, id: Int) -> Bool {
  let mut i = 0;
  while i < list.tasks.len() {
    let task = list.tasks.get(i).unwrap();
    if task.id == id {
      list.tasks.set(i, Task{
        id: task.id, title: task.title.clone(),
        status: TaskStatus.Completed, priority: task.priority
      });
      return true;
    };
    i += 1;
  };
  false
}

fn remove_task(list: &mut TodoList, id: Int) -> Bool {
  let mut i = 0;
  while i < list.tasks.len() {
    if list.tasks.get(i).unwrap().id == id {
      list.tasks.remove(i);
      return true;
    };
    i += 1;
  };
  false
}
```

### Listing Tasks

```xiom
fn list_pending(list: &TodoList) {
  let mut i = 0;
  while i < list.tasks.len() {
    let task = list.tasks.get(i).unwrap();
    if task.status == TaskStatus.Pending {
      io.println(task.id);
      io.println(task.title);
    };
    i += 1;
  };
}

fn count_pending(list: &TodoList) -> Int {
  let mut count = 0;
  let mut i = 0;
  while i < list.tasks.len() {
    if list.tasks.get(i).unwrap().status == TaskStatus.Pending {
      count += 1;
    };
    i += 1;
  };
  count
}
```

